// Shared UI for the supplier revenue calculator (Deal card and App Page).
import React, { useCallback, useEffect, useState } from 'react';
import {
  Accordion, Alert, Button, Checkbox, DateInput, Divider, Flex, Heading, List, LoadingSpinner, NumberInput,
  Select, Table, TableBody, TableCell, TableHead, TableHeader, TableRow, Tag, Text, Tile, ToggleGroup, hubspot,
} from '@hubspot/ui-extensions';

type Result = { key: string; supplier: string; product: string; comms: number; term: number | null; end: string | null; annual: number; total: number; warn: string[]; fail: string[]; renewal: boolean };
type CalcResponse = { errors: string[]; available: Result[]; ruledOut: Result[]; today: string; considered?: number; stipMonth: string | null; error?: string };
type DealContext = { dealName: string; fuel: 'E' | 'G'; aq: number | null; start: string | null; hh: string; current: string; currentSupplierText: string; notes: string[]; saved: null | { supplier: string; product: string; total: number | null; at: string } };
type DateVal = { year: number; month: number; date: number };

const SUPPLIERS = [
  ['', 'New business (none of these)'], ['bg', 'British Gas'], ['corona', 'Corona Energy'], ['crown', 'Crown'], ['drax', 'Drax'], ['edf', 'EDF'],
  ['engie', 'Engie'], ['npower', 'Npower'], ['shell', 'Shell Energy'], ['smartest', 'Smartest Energy'], ['total', 'TotalEnergies'],
].map(([value, label]) => ({ value, label }));
const SECTORS = [
  ['general', 'General commercial'], ['charity', 'Charity'], ['schoolnhs', 'School or NHS (not a hospital)'], ['hospital', 'Hospital'], ['pub', 'Pub, bar or club'],
  ['restaurant', 'Restaurant'], ['takeaway', 'Takeaway'], ['carehome', 'Care home'], ['housing', 'Housing association or student accommodation'],
  ['agriculture', 'Agriculture'], ['domestic', 'Domestic supply'],
].map(([value, label]) => ({ value, label }));
const TERMS = [{ value: 'max', label: 'Longest each product allows' }, ...[12, 24, 36, 48, 60, 72].map((m) => ({ value: String(m), label: `${m} months` }))];
const YNU = [{ value: 'unsure', label: 'Not sure' }, { value: 'yes', label: 'Yes' }, { value: 'no', label: 'No' }];

const gbp = (v: number) => v.toLocaleString('en-GB', { style: 'currency', currency: 'GBP', maximumFractionDigits: 0 });
const pence = (v: number) => `${Math.round(v * 100) / 100}p`;
const uk = (iso: string | null) => (iso ? iso.split('-').reverse().join('/') : '');
const toDate = (iso: string | null): DateVal | undefined => { if (!iso) return undefined; const [y, m, d] = iso.split('-').map(Number); return { year: y, month: m - 1, date: d }; };
const fromDate = (v: DateVal | null) => (v ? `${v.year}-${String(v.month + 1).padStart(2, '0')}-${String(v.date).padStart(2, '0')}` : '');
const firstOfNextMonth = () => { const d = new Date(); const n = new Date(Date.UTC(d.getFullYear(), d.getMonth() + 1, 1)); return n.toISOString().slice(0, 10); };
const label = (r: Result) => r.supplier + (r.product ? ` ${r.product}` : '');

export const RevenueCalculator = ({ dealId }: { dealId?: string | null }) => {
  const [form, setForm] = useState({
    fuel: 'E' as 'E' | 'G', aq: null as number | null, start: firstOfNextMonth(), term: 'max', current: '', sector: 'general', structure: 'ltd',
    trading: '2', smart: 'unsure', dd: 'unsure', hh: 'unsure', micro: false, indep: false, bgTrial: true, role: 'se',
  });
  const [ctx, setCtx] = useState<DealContext | null>(null);
  const [loadingCtx, setLoadingCtx] = useState(!!dealId);
  const [busy, setBusy] = useState(false);
  const [res, setRes] = useState<CalcResponse | null>(null);
  const [err, setErr] = useState<string | null>(null);
  const [saveMsg, setSaveMsg] = useState<{ ok: boolean; text: string } | null>(null);
  const set = (k: keyof typeof form) => (v: unknown) => setForm((f) => ({ ...f, [k]: v }));

  const calculate = useCallback(async (f = form) => {
    setBusy(true); setErr(null); setSaveMsg(null);
    try {
      const r = await hubspot.serverless('stip_calculate', { parameters: { deal: { ...f, trading: Number(f.trading) } } });
      const body = (r && (r.body ?? r)) as CalcResponse;
      if (body.error) setErr(body.error); else setRes(body);
    } catch (e) { setErr(`Couldn't calculate: ${(e as Error).message}`); }
    setBusy(false);
  }, [form]);

  useEffect(() => {
    if (!dealId) return;
    (async () => {
      try {
        const r = await hubspot.serverless('stip_deal_context', { parameters: { dealId } });
        const c = (r && (r.body ?? r)) as DealContext & { error?: string };
        if (c.error) { setErr(c.error); setLoadingCtx(false); return; }
        setCtx(c);
        const next = { ...form, fuel: c.fuel, aq: c.aq, start: c.start || form.start, hh: c.hh || 'unsure', current: c.current || '' };
        setForm(next); setLoadingCtx(false);
        if (next.aq) calculate(next);
      } catch (e) { setErr(`Couldn't read the deal: ${(e as Error).message}`); setLoadingCtx(false); }
    })();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [dealId]);

  const save = async (r: Result) => {
    setSaveMsg(null);
    try {
      const out = await hubspot.serverless('stip_save_estimate', { parameters: { dealId, supplier: r.supplier, product: r.product, comms: r.comms, term: r.term, annual: r.annual, total: r.total } });
      const body = out && (out.body ?? out);
      setSaveMsg(body && body.saved ? { ok: true, text: `Saved ${label(r)}, ${gbp(r.total)} over the contract, to this deal.` } : { ok: false, text: (body && body.error) || "Couldn't save to the deal." });
    } catch (e) { setSaveMsg({ ok: false, text: `Couldn't save to the deal: ${(e as Error).message}` }); }
  };

  if (loadingCtx) return <LoadingSpinner label="Reading the deal's meters and CED" />;
  const best = res && res.available[0];

  return (
    <Flex direction="column" gap="md">
      {ctx && ctx.notes.length > 0 && (
        <Alert title="Check before you rely on these figures" variant="info"><List>{ctx.notes.map((n) => <Text key={n}>{n}</Text>)}</List></Alert>
      )}
      {ctx && ctx.saved && <Text variant="microcopy">Last saved on this deal: {ctx.saved.supplier} {ctx.saved.product}{ctx.saved.total ? `, ${gbp(ctx.saved.total)}` : ''}.</Text>}

      <Tile>
        <Heading>Deal details</Heading>
        <Flex direction="row" wrap="wrap" gap="sm">
          <ToggleGroup toggleType="radioButtonList" name="fuel" label="Fuel" inline value={form.fuel} onChange={set('fuel')} options={[{ label: 'Electric', value: 'E' }, { label: 'Gas', value: 'G' }]} />
          <NumberInput name="aq" label="Annual consumption (kWh)" value={form.aq ?? undefined} min={1} onChange={set('aq')} />
          <DateInput name="start" label="Contract start date" format="LL" value={toDate(form.start)} onChange={(v) => set('start')(fromDate(v))} />
          <Select name="term" label="Contract length" value={form.term} options={TERMS} onChange={set('term')} />
          <Select name="current" label="Current supplier" value={form.current} options={SUPPLIERS} onChange={set('current')} />
          <Select name="sector" label="Sector" value={form.sector} options={SECTORS} onChange={set('sector')} />
          <Select name="structure" label="Business type" value={form.structure} onChange={set('structure')} options={[{ value: 'ltd', label: 'Limited company' }, { value: 'sole', label: 'Sole trader' }, { value: 'partner', label: 'Partnership' }, { value: 'other', label: 'Other' }]} />
          <Select name="trading" label="Trading for" value={form.trading} onChange={set('trading')} options={[{ value: '2', label: '2+ years' }, { value: '1', label: '1 to 2 years' }, { value: '0', label: 'Under 1 year' }]} />
          <Select name="smart" label="Smart meter" value={form.smart} options={YNU} onChange={set('smart')} />
          <Select name="dd" label="Direct Debit" value={form.dd} options={YNU} onChange={set('dd')} />
          <Select name="hh" label="Half hourly (HH) meter" value={form.hh} options={YNU} onChange={set('hh')} />
          <Select name="role" label="Npower post-MTP rate" value={form.role} onChange={set('role')} options={[{ value: 'se', label: 'Sales Exec' }, { value: 'tm', label: 'TM/BDM' }]} />
        </Flex>
        <Flex direction="row" wrap="wrap" gap="md">
          <Checkbox name="micro" checked={form.micro} onChange={set('micro')}>Micro business</Checkbox>
          <Checkbox name="indep" checked={form.indep} onChange={set('indep')}>{form.fuel === 'G' ? 'Meter is on an IGT network' : 'Meter is on an IDNO network'}</Checkbox>
          <Checkbox name="bgTrial" checked={form.bgTrial} onChange={set('bgTrial')}>British Gas 3p trial is running</Checkbox>
        </Flex>
        <Button variant="primary" onClick={() => calculate()} disabled={busy}>{busy ? 'Calculating…' : 'Rank suppliers'}</Button>
      </Tile>

      {err && <Alert title="Something went wrong" variant="error">{err}</Alert>}
      {res && res.errors.length > 0 && <Alert title="Add the missing details" variant="warning">{res.errors.join('. ')}</Alert>}
      {saveMsg && <Alert title={saveMsg.ok ? 'Saved' : "Couldn't save"} variant={saveMsg.ok ? 'success' : 'error'}>{saveMsg.text}</Alert>}

      {res && res.errors.length === 0 && (
        <>
          {best ? (
            <Tile>
              <Text variant="microcopy">Most revenue for {Number(form.aq).toLocaleString('en-GB')} kWh of {form.fuel === 'E' ? 'electricity' : 'gas'}</Text>
              <Heading>{label(best)}: {gbp(best.total)}</Heading>
              <Text>{pence(best.comms)}/kWh for {best.term} months, ending {uk(best.end)}. {gbp(best.annual)} a year.</Text>
            </Tile>
          ) : (
            <Alert title="No supplier can quote this deal" variant="warning">See the reasons below. A different start date or contract length often opens options up.</Alert>
          )}

          {res.available.length > 0 && (
            <>
              <Heading>Available suppliers ({res.available.length} of {res.considered})</Heading>
              <Table bordered density="condensed">
                <TableHead>
                  <TableRow>
                    <TableHeader width="min">#</TableHeader><TableHeader>Supplier</TableHeader><TableHeader align="right">Comms</TableHeader>
                    <TableHeader align="right">Term</TableHeader><TableHeader>Ends</TableHeader><TableHeader align="right">Per year</TableHeader>
                    <TableHeader align="right">Over contract</TableHeader>{dealId ? <TableHeader width="min"> </TableHeader> : null}
                  </TableRow>
                </TableHead>
                <TableBody>
                  {res.available.map((r, i) => (
                    <TableRow key={r.key}>
                      <TableCell>{i + 1}</TableCell>
                      <TableCell>{label(r)} {r.renewal ? <Tag variant="info">Renewal</Tag> : null} {r.warn.length ? <Tag variant="warning">{r.warn.length} to check</Tag> : null}</TableCell>
                      <TableCell align="right">{pence(r.comms)}/kWh</TableCell>
                      <TableCell align="right">{r.term} months</TableCell>
                      <TableCell>{uk(r.end)}</TableCell>
                      <TableCell align="right">{gbp(r.annual)}</TableCell>
                      <TableCell align="right">{gbp(r.total)}</TableCell>
                      {dealId ? <TableCell><Button size="xs" variant="secondary" onClick={() => save(r)}>Save to deal</Button></TableCell> : null}
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
              <Accordion title="Things to check for each supplier" size="sm">
                {res.available.filter((r) => r.warn.length).map((r) => (
                  <Flex key={r.key} direction="column" gap="xs"><Text format={{ fontWeight: 'bold' }}>{label(r)}</Text><List>{r.warn.map((w) => <Text key={w}>{w}</Text>)}</List></Flex>
                ))}
              </Accordion>
            </>
          )}

          {res.ruledOut.length > 0 && (
            <Accordion title={`Can't quote (${res.ruledOut.length} ruled out)`} size="sm">
              {res.ruledOut.map((r) => (
                <Flex key={r.key} direction="column" gap="xs"><Text format={{ fontWeight: 'bold' }}>{label(r)}</Text><List>{r.fail.map((f) => <Text key={f}>{f}</Text>)}</List></Flex>
              ))}
            </Accordion>
          )}

          <Divider />
          <Text variant="microcopy">
            Commission only: max p/kWh × annual consumption × contract years, assuming the full max comms and flat consumption.
            Stipulations: {res.stipMonth ? new Date(`${res.stipMonth}T00:00:00Z`).toLocaleDateString('en-GB', { month: 'long', year: 'numeric', timeZone: 'UTC' }) : 'unknown month'}.
            Credit checks show as things to check rather than ruling a supplier out.
          </Text>
        </>
      )}
    </Flex>
  );
};
